-- Table structure for production_schedule_plan
DROP TABLE IF EXISTS `production_schedule_plan`;
CREATE TABLE `production_schedule_plan` (
  `id` bigint NOT NULL COMMENT '排产方案ID',
  `task_id` bigint NOT NULL COMMENT '对应算法任务ID',
  `schedule_name` varchar(128) NOT NULL COMMENT '方案名称',
  `schedule_date` date NOT NULL COMMENT '排产日期',
  `plan_start_time` datetime NOT NULL COMMENT '计划开始时间，对应daily_plan.timestamp',
  `plan_horizon` int NOT NULL COMMENT '计划跨度，当前为24',
  `plan_unit` varchar(32) NOT NULL DEFAULT 'hour' COMMENT '计划单位',
  `data_granularity` varchar(32) NOT NULL DEFAULT '1 minute' COMMENT '模型底层数据粒度',
  `status` varchar(32) NOT NULL DEFAULT 'SUCCESS' COMMENT '方案状态',
  `objective` varchar(64) DEFAULT NULL COMMENT '优化目标',
  `elec_coefficient` decimal(12,4) DEFAULT NULL COMMENT '电耗系数，kWh/吨',
  `ec_baseline` decimal(12,4) DEFAULT NULL COMMENT '优化前EC基准值，kWh/吨',
  `ec_optimized` decimal(12,4) DEFAULT NULL COMMENT '优化后EC值，kWh/吨',
  `ec_reduction` decimal(12,4) DEFAULT NULL COMMENT 'EC降低百分比',
  `optimal_temperature` decimal(12,4) DEFAULT NULL COMMENT '最优温度，℃',
  `optimal_speed` decimal(12,4) DEFAULT NULL COMMENT '最优速度',
  `total_demand` decimal(14,6) DEFAULT NULL COMMENT '总需求',
  `total_production` decimal(14,6) DEFAULT NULL COMMENT '总排产量',
  `total_energy` decimal(14,6) DEFAULT NULL COMMENT '总预测电耗，kWh',
  `raw_plan_json` longtext COMMENT 'daily_plan.json原文',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_by` bigint DEFAULT NULL,
  `update_by` bigint DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_schedule_date` (`schedule_date`),
  KEY `idx_task_id` (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='排产方案主表';

