-- Table structure for production_schedule_detail
DROP TABLE IF EXISTS `production_schedule_detail`;
CREATE TABLE `production_schedule_detail` (
  `id` bigint NOT NULL COMMENT '明细ID',
  `schedule_id` bigint NOT NULL COMMENT '排产方案ID',
  `hour_index` int NOT NULL COMMENT '小时序号，0-23',
  `start_time` datetime NOT NULL COMMENT '小时开始时间',
  `end_time` datetime NOT NULL COMMENT '小时结束时间',
  `demand` decimal(14,6) DEFAULT NULL COMMENT '小时需求',
  `production` decimal(14,6) NOT NULL COMMENT '小时排产量，吨',
  `elec_forecast` decimal(14,6) NOT NULL COMMENT '小时预测电耗，kWh',
  `line_id` bigint DEFAULT NULL COMMENT '产线ID，当前JSON未提供',
  `equipment_id` bigint DEFAULT NULL COMMENT '设备ID，当前JSON未提供',
  `order_id` bigint DEFAULT NULL COMMENT '订单ID，当前JSON未提供',
  `equipment_load_rate` decimal(8,2) DEFAULT NULL COMMENT '设备负荷率',
  `conflict_flag` tinyint NOT NULL DEFAULT '0' COMMENT '是否存在冲突',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_schedule_hour` (`schedule_id`,`hour_index`),
  KEY `idx_schedule_time` (`schedule_id`,`start_time`,`end_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='排产方案明细表';

